window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8585adce2c77e231"]={"versions": [{"id": "FIG-8585adce2c77e231", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR Generic Structure Template (GST). Das Diagramm spezifiziert die Vererbungshierarchie und Kompositionsbeziehungen der zentralen abstrakten Basisklasse <code>Identifiable</code> zur Definition referenzierbarer und dokumentierbarer Modellelemente innerhalb der AUTOSAR-Modellarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Referrable</code> (abstrakt): Oberste Basisklasse mit Attribut <code>+ shortName: Identifier</code>.</li>\n<li><code>MultilanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>; besitzt eine gerichtete Komposition zu <code>MultilanguageLongName</code> (Rollenname <code>+longName</code>, Multiplizität <code>0..1</code>).</li>\n<li><code>Identifiable</code> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code> mit Attributen <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>. Komponiert folgende Elemente:</li>\n<li><code>MultiLanguageOverviewParagraph</code> über Rolle <code>+desc</code> [0..1]</li>\n<li><code>AdminData</code> über Rolle <code>+adminData</code> [0..1] mit Attribut <code>+ language: LEnum [0..1]</code></li>\n<li><code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) über Rolle <code>+introduction</code> [0..1]</li>\n<li><code>Annotation</code> / <code>GeneralAnnotation</code> über Rolle <code>+annotation</code> [0..*]</li>\n<li>Kommentar-Notiz zur XML-Serialisierungsreihenfolge (<code>xml.sequenceOffset</code>):</li>\n<li><code>desc</code>: -60</li>\n<li><code>category</code>: -50</li>\n<li><code>adminData</code>: -40</li>\n<li><code>introduction</code>: -30</li>\n<li><code>annotation</code>: -25</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeit-Zustandsübergänge. Die Beziehungen definieren strukturelle Verschachtelungen (Kompositionen) und Typvererbungen bei der Instanziierung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>Identifiable</code> dient als normative Basisklasse für alle eindeutig über einen Pfad identifizierbaren AUTOSAR-Elemente.</li>\n<li>Die über <code>xml.sequenceOffset</code> definierten Offsets legen verbindlich die relative XML-Schema-Reihenfolge der Kindelemente innerhalb des serialisierten XML-Tags von <code>Identifiable</code> fest.</li>\n<li>Der Stereotyp <code>«atpMixed»</code> an <code>DocumentationBlock</code> signalisiert Mischinhalt (Mixed Content) aus Text und XML-Tags in der Dokumentationsstruktur.</li>\n<li><code>shortName</code> ist verpflichtend für die Referenzierbarkeit, während Beschreibungs-, Administrations- und Annotationsdaten optional gehalten sind.</li>\n</ul>"}, {"id": "FIG-922d8a76ce675306", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR Generic Structure Template (GST). Das Diagramm spezifiziert die Vererbungshierarchie und Kompositionsbeziehungen der zentralen abstrakten Basisklasse <code>Identifiable</code> zur Definition referenzierbarer und dokumentierbarer Modellelemente innerhalb der AUTOSAR-Modellarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Referrable</code> (abstrakt): Oberste Basisklasse mit Attribut <code>+ shortName: Identifier</code>.</li>\n<li><code>MultilanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>; besitzt eine gerichtete Komposition zu <code>MultilanguageLongName</code> (Rollenname <code>+longName</code>, Multiplizität <code>0..1</code>).</li>\n<li><code>Identifiable</code> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code> mit Attributen <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>. Komponiert folgende Elemente:</li>\n<li><code>MultiLanguageOverviewParagraph</code> über Rolle <code>+desc</code> [0..1]</li>\n<li><code>AdminData</code> über Rolle <code>+adminData</code> [0..1] mit Attribut <code>+ language: LEnum [0..1]</code></li>\n<li><code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) über Rolle <code>+introduction</code> [0..1]</li>\n<li><code>Annotation</code> / <code>GeneralAnnotation</code> über Rolle <code>+annotation</code> [0..*]</li>\n<li>Kommentar-Notiz zur XML-Serialisierungsreihenfolge (<code>xml.sequenceOffset</code>):</li>\n<li><code>desc</code>: -60</li>\n<li><code>category</code>: -50</li>\n<li><code>adminData</code>: -40</li>\n<li><code>introduction</code>: -30</li>\n<li><code>annotation</code>: -25</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeit-Zustandsübergänge. Die Beziehungen definieren strukturelle Verschachtelungen (Kompositionen) und Typvererbungen bei der Instanziierung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>Identifiable</code> dient als normative Basisklasse für alle eindeutig über einen Pfad identifizierbaren AUTOSAR-Elemente.</li>\n<li>Die über <code>xml.sequenceOffset</code> definierten Offsets legen verbindlich die relative XML-Schema-Reihenfolge der Kindelemente innerhalb des serialisierten XML-Tags von <code>Identifiable</code> fest.</li>\n<li>Der Stereotyp <code>«atpMixed»</code> an <code>DocumentationBlock</code> signalisiert Mischinhalt (Mixed Content) aus Text und XML-Tags in der Dokumentationsstruktur.</li>\n<li><code>shortName</code> ist verpflichtend für die Referenzierbarkeit, während Beschreibungs-, Administrations- und Annotationsdaten optional gehalten sind.</li>\n</ul>"}, {"id": "FIG-6b03ce19dd689f8d", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR Generic Structure Template (GST). Das Diagramm spezifiziert die Vererbungshierarchie und Kompositionsbeziehungen der zentralen abstrakten Basisklasse <code>Identifiable</code> zur Definition referenzierbarer und dokumentierbarer Modellelemente innerhalb der AUTOSAR-Modellarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Referrable</code> (abstrakt): Oberste Basisklasse mit Attribut <code>+ shortName: Identifier</code>.</li>\n<li><code>MultilanguageReferrable</code> (abstrakt): Spezialisierung von <code>Referrable</code>; besitzt eine gerichtete Komposition zu <code>MultilanguageLongName</code> (Rollenname <code>+longName</code>, Multiplizität <code>0..1</code>).</li>\n<li><code>Identifiable</code> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code> mit Attributen <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>. Komponiert folgende Elemente:</li>\n<li><code>MultiLanguageOverviewParagraph</code> über Rolle <code>+desc</code> [0..1]</li>\n<li><code>AdminData</code> über Rolle <code>+adminData</code> [0..1] mit Attribut <code>+ language: LEnum [0..1]</code></li>\n<li><code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) über Rolle <code>+introduction</code> [0..1]</li>\n<li><code>Annotation</code> / <code>GeneralAnnotation</code> über Rolle <code>+annotation</code> [0..*]</li>\n<li>Kommentar-Notiz zur XML-Serialisierungsreihenfolge (<code>xml.sequenceOffset</code>):</li>\n<li><code>desc</code>: -60</li>\n<li><code>category</code>: -50</li>\n<li><code>adminData</code>: -40</li>\n<li><code>introduction</code>: -30</li>\n<li><code>annotation</code>: -25</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeit-Zustandsübergänge. Die Beziehungen definieren strukturelle Verschachtelungen (Kompositionen) und Typvererbungen bei der Instanziierung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>Identifiable</code> dient als normative Basisklasse für alle eindeutig über einen Pfad identifizierbaren AUTOSAR-Elemente.</li>\n<li>Die über <code>xml.sequenceOffset</code> definierten Offsets legen verbindlich die relative XML-Schema-Reihenfolge der Kindelemente innerhalb des serialisierten XML-Tags von <code>Identifiable</code> fest.</li>\n<li>Der Stereotyp <code>«atpMixed»</code> an <code>DocumentationBlock</code> signalisiert Mischinhalt (Mixed Content) aus Text und XML-Tags in der Dokumentationsstruktur.</li>\n<li><code>shortName</code> ist verpflichtend für die Referenzierbarkeit, während Beschreibungs-, Administrations- und Annotationsdaten optional gehalten sind.</li>\n</ul>"}], "trans": [{"from": "FIG-8585adce2c77e231", "to": "FIG-922d8a76ce675306", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Formatierung der Attribut-Typtrennung: In den Klassen <code>Referrable</code>, <code>Identifiable</code> und <code>AdminData</code> wurde der Leerraum vor dem Doppelpunkt entfernt (<code>shortName :Identifier</code>, <code>category :CategoryString</code>, <code>uuid :String</code>, <code>language :LEnum</code>).</li>\n</ul>"}, {"from": "FIG-922d8a76ce675306", "to": "FIG-6b03ce19dd689f8d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
